command:
install -d -m 0750 -o root -g root /var/log/inventory && cat > /etc/rsyslog.d/20-inventory-collector.conf <<'ANTRIEB_EOF'
module(load="imtcp")
input(type="imtcp" port="601" address="10.100.129.10" ruleset="inventory_remote")

ruleset(name="inventory_remote") {
    if ($fromhost-ip == "10.100.129.11" and $programname == "inventory") then {
        action(type="omfile" file="/var/log/inventory/node2.log" fileCreateMode="0640" dirCreateMode="0750")
    }
    stop
}
ANTRIEB_EOF
restorecon -RF /var/log/inventory /etc/rsyslog.d/20-inventory-collector.conf && rsyslogd -N1

